import { appRoutePaths } from "./appRoutePaths";
import type { AppRoutePath } from "./appRoutePaths";

const GENERATED_HEADER =
	"# Generated by src/routing/runGenerateCloudflarePagesRouting.ts — do not edit by hand.\n";

export function redirectRulesForRoute(route: AppRoutePath): string[] {
	if (route.path === "/") {
		return [];
	}

	const spaShell = "/";

	if (route.exact) {
		return [`${route.path} ${spaShell} 200`];
	}

	return [
		`${route.path} ${spaShell} 200`,
		`${route.path}/* ${spaShell} 200`,
	];
}

export function generateCloudflareRedirectsFile(): string {
	const staticRules: string[] = [];
	const dynamicRules: string[] = [];

	for (const route of appRoutePaths) {
		const rules = redirectRulesForRoute(route);
		for (const rule of rules) {
			if (rule.includes("*")) {
				dynamicRules.push(rule);
			} else {
				staticRules.push(rule);
			}
		}
	}

	const lines = [
		GENERATED_HEADER.trim(),
		...staticRules,
		...dynamicRules,
	];

	return `${lines.join("\n")}\n`;
}

export function assertAppRoutesCoveredByRedirects(
	routes: readonly AppRoutePath[],
	redirectsContent: string,
): void {
	const missing: string[] = [];

	for (const route of routes) {
		if (route.path === "/") {
			continue;
		}

		const needsExact = route.exact === true;
		const needsSplat = !needsExact;

		const hasExact = redirectsContent.includes(`${route.path} / 200`);
		const hasSplat = redirectsContent.includes(`${route.path}/* / 200`);

		if (needsExact && !hasExact) {
			missing.push(`${route.path} (exact)`);
		}

		if (needsSplat && (!hasExact || !hasSplat)) {
			missing.push(`${route.path} (prefix + splat)`);
		}
	}

	if (missing.length > 0) {
		throw new Error(
			`Router paths missing from generated _redirects: ${missing.join(", ")}`,
		);
	}
}
